DWARF_SHA = '2ab5f671653ffe1817a31cd5d2a0d2e2a9c6abd46abf53042d71930dfc3086bb'

HARNESS = r'''pub use c6_core::unit;
#[path="MODULE"] pub mod player_influence;
fn main(){let a:Vec<_>=std::env::args().collect();let b=std::fs::read(&a[1]).unwrap();let generous=unit::Limits{max_bytes:b.len(),max_items:b.len()};let(v,n,items)=player_influence::Influence::decode_prefix_with_items(&b,generous).unwrap();assert_eq!(n,b.len());let exact=unit::Limits{max_bytes:n,max_items:items};let(out,wi)=v.encode_with_items(exact).unwrap();assert_eq!(wi,items);assert_eq!(out,b);assert_eq!(v,player_influence::Influence::decode(&b,exact).unwrap());for end in 0..n{assert!(player_influence::Influence::decode(&b[..end],exact).is_err());}for lim in [unit::Limits{max_bytes:n-1,..exact},unit::Limits{max_items:items-1,..exact}]{assert!(player_influence::Influence::decode(&b,lim).is_err());assert!(v.encode(lim).is_err());}std::fs::write(&a[2],out).unwrap();println!("{} {}",n,items);}
'''

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--assets',type=Path,default=ROOT.parent/'c6-assets-linux')
    p.add_argument('--private-root',type=Path,default=ROOT.parent/'c6-ghidra')
    p.add_argument('--source-commit',required=True)
    p.add_argument('--output',type=Path,required=True)
    args=p.parse_args()
    game=Elf(args.assets/'libGameCore_XP2.so',GAME_SHA)
    Elf(args.assets/'Civ6',HOST_SHA)
    for a,n,name,digest in METHODS:
        if sha(game.read(a,n))!=digest:raise ValueError('method mismatch: '+name)
    if struct.unpack('<I',game.read(0x2f61f44,4))[0]!=22:raise ValueError('version mismatch')
    for address,body in VIRTUALS:
        if game.relocated_pointer(address)!=body:raise ValueError("virtual save/load binding mismatch")
    relocations=relocation_symbols(game)
    for site,plt,body,kind in BINDINGS:
        code=game.read(site,5)
